function defaultSlayerState(){return {currentTask:null,streak:0,streakBaseline:0,trackingStartedAt:null,points:0,boostTarget:250,preferredMaster:'konar',taskHistory:[],records:{},blocks:[],favorites:[],setup:{cannon:true,barrage:true,npcContact:false,expeditious:true,ironman:false},notes:'',createdAt:new Date().toISOString()}}

try{if(!localStorage.getItem(SLAYER_BACKUP_KEY)){const profiles=localStorage.getItem(PROFILES_KEY),legacy=localStorage.getItem(STORE_KEY);if(profiles||legacy)localStorage.setItem(SLAYER_BACKUP_KEY,profiles||legacy)}}catch{}

const slayerOriginalDefaultState=defaultState;
defaultState=function(){const next=slayerOriginalDefaultState();next.slayer=defaultSlayerState();return next};
const slayerOriginalMergeDefaults=mergeDefaults;
mergeDefaults=function(saved){const merged=slayerOriginalMergeDefaults(saved||{}),base=defaultSlayerState(),incoming=saved?.slayer||{};merged.slayer={...base,...incoming,setup:{...base.setup,...incoming.setup},records:incoming.records||{},blocks:incoming.blocks||[],favorites:incoming.favorites||[],taskHistory:incoming.taskHistory||[]};return merged};
state=mergeDefaults(state);activeProfile().state=state;try{persistProfiles()}catch{}

Object.assign(ui,{slayerTab:ui.slayerTab||'task',slayerSearch:'',slayerFilter:'all',slayerSelectedId:null,slayerOnlyReady:false,slayerImageLoading:false,slayerPlannerView:'blocks',slayerEditingStreak:false,slayerEditingPoints:false,slayerStartId:null});
const slayerNavIndex=navItems.findIndex(item=>item[0]==='pvm');
if(!navItems.some(item=>item[0]==='slayer'))navItems.splice(slayerNavIndex,0,['slayer','☠','Central de Slayer']);
titles.slayer=['CAÇADAS E RECOMPENSAS','Central de Slayer'];

let slayerImages={},slayerImagesAttempted=false;try{slayerImages=JSON.parse(localStorage.getItem(SLAYER_IMAGE_KEY)||'{}')||{}}catch{}

function slayerEntry(value){const needle=slug(value);return slayerCatalog.find(item=>item.id===needle||slug(item.name)===needle)||null}
function slayerRecord(idValue){const key=slug(idValue);if(!state.slayer.records[key])state.slayer.records[key]={kills:0,notes:'',preferredLocation:'',lastDone:null};return state.slayer.records[key]}
function slayerCombatLevel(){const attack=skill('Attack')?.current||1,strength=skill('Strength')?.current||1,defence=skill('Defence')?.current||1,hp=skill('Hitpoints')?.current||10,prayer=skill('Prayer')?.current||1,ranged=skill('Ranged')?.current||1,magic=skill('Magic')?.current||1;return Math.floor(.25*(defence+hp+Math.floor(prayer/2))+.325*Math.max(attack+strength,Math.floor(ranged*1.5),Math.floor(magic*1.5)))}
function slayerReady(item){return (skill('Slayer')?.current||1)>=item.slayerLevel}
function slayerWikiUrl(item){return `https://oldschool.runescape.wiki/w/${encodeURIComponent((item?.wiki||item?.name||'Slayer').replace(/ /g,'_'))}`}
function slayerImage(item){return slayerImages[item.id]||''}
function slayerInitials(name){return name.split(/\s+/).map(word=>word[0]).join('').slice(0,2).toUpperCase()}
function slayerPortrait(item,size='normal'){const image=slayerImage(item);return `<span class="slayer-portrait ${size}">${image?`<img src="${esc(image)}" alt="${esc(item.name)}" loading="lazy" onerror="this.remove()">`:slayerInitials(item.name)}</span>`}
function currentSlayerProgress(){const task=state.slayer.currentTask;if(!task)return 0;return clamp(((Math.max(0,task.amount-task.remaining))/Math.max(1,task.amount))*100)}
function milestoneMultiplier(streak){if(streak>0&&streak%1000===0)return 50;if(streak>0&&streak%250===0)return 35;if(streak>0&&streak%100===0)return 25;if(streak>0&&streak%50===0)return 15;if(streak>0&&streak%10===0)return 5;return 1}
function nextSlayerMilestone(streak=state.slayer.streak){return [10,50,100,250,1000].map(base=>Math.floor(streak/base)*base+base).sort((a,b)=>a-b)[0]}
function milestonePoints(masterKey,streak){const master=slayerMasters[masterKey]||slayerMasters.konar;if(masterKey==='turael'||streak<=5)return 0;return master.points*milestoneMultiplier(streak)}
function slayerMasterKey(task){return task?.masterKey||Object.entries(slayerMasters).find(([,item])=>item.name===task?.master)?.[0]||'turael'}
function slayerMasterOptions(selectedKey=''){return Object.entries(slayerMasters).map(([key,item])=>`<option value="${key}" ${selectedKey===key?'selected':''}>${esc(item.name)} · ${item.points} pts</option>`).join('')}
function slayerRewardPreview(masterKey,streak=state.slayer.streak+1){const master=slayerMasters[masterKey]||slayerMasters.turael,multiplier=milestoneMultiplier(streak),points=milestonePoints(masterKey,streak),reason=masterKey==='turael'?'Turael/Aya mantém a streak, mas não dá pontos.':streak<=5?'As cinco primeiras tasks da streak não concedem pontos.':multiplier>1?`${master.points} pontos × bônus ${multiplier} da task #${streak}.`:`${master.points} pontos normais pela task #${streak}.`;return {master,multiplier,points,reason}}
function slayerCanUndo(){const last=state.slayer.taskHistory[0],baseline=Math.max(0,Number(state.slayer.streakBaseline)||0),started=state.slayer.trackingStartedAt?new Date(state.slayer.trackingStartedAt).getTime():0;return !!last&&Number(last.streak)>baseline&&(!started||new Date(last.date).getTime()>=started)}
function slayerTag(text){return `<span class="slayer-tag">${esc(text)}</span>`}

async function loadSlayerImages(force=false){if(ui.slayerImageLoading)return;const pending=slayerCatalog.filter(item=>force||!slayerImages[item.id]);if(!pending.length)return;slayerImagesAttempted=true;ui.slayerImageLoading=true;if(route==='slayer')render();try{for(let start=0;start<pending.length;start+=15){const batch=pending.slice(start,start+15),titlesParam=batch.map(item=>slayerImageTitles[item.id]||item.wiki).join('|'),response=await fetch(`${SLAYER_WIKI_API}?action=query&format=json&origin=*&redirects=1&prop=pageimages&piprop=thumbnail&pithumbsize=180&titles=${encodeURIComponent(titlesParam)}`,{cache:force?'no-store':'force-cache',signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error(`Wiki ${response.status}`);const payload=await response.json(),pages=Object.values(payload.query?.pages||{});batch.forEach(item=>{const expected=slayerImageTitles[item.id]||item.wiki,page=pages.find(entry=>slug(entry.title)===slug(expected));if(page?.thumbnail?.source)slayerImages[item.id]=page.thumbnail.source})}try{localStorage.setItem(SLAYER_IMAGE_KEY,JSON.stringify(slayerImages))}catch{}if(route==='slayer')render()}catch(error){toast(`Imagens do Slayer: ${error.name==='TimeoutError'?'a Wiki demorou para responder':error.message}`)}finally{ui.slayerImageLoading=false;if(route==='slayer')render()}}

function slayerTabs(){return `<div class="rune-tabs slayer-tabs"><button data-slayer-tab="task" class="${ui.slayerTab==='task'?'active':''}">☠ Task atual</button><button data-slayer-tab="bestiary" class="${ui.slayerTab==='bestiary'?'active':''}">⌕ Bestiário</button><button data-slayer-tab="boost" class="${ui.slayerTab==='boost'?'active':''}">⚡ Turael Boost</button><button data-slayer-tab="planner" class="${ui.slayerTab==='planner'?'active':''}">▤ Meu Slayer</button></div>`}

function slayerHero(){const task=state.slayer.currentTask,next=nextSlayerMilestone(),master=slayerMasters[state.slayer.preferredMaster]||slayerMasters.konar;return `<section class="slayer-hero"><div><span class="eyebrow">SLAYER ${skill('Slayer')?.current||1}</span><h2>${task?esc(task.name):'A próxima caçada começa aqui'}</h2><p>${task?`${Math.max(0,task.remaining)} de ${task.amount} restantes · ${esc(task.master)}`:'Registre a task manualmente e o painel cuida do progresso, rota e preparação.'}</p></div><div class="slayer-hero-stats"><button type="button" class="slayer-stat-edit" data-slayer-edit-streak title="Editar streak atual"><small>STREAK</small><strong>${state.slayer.streak}</strong><em>✎ editar</em></button><button type="button" class="slayer-stat-edit" data-slayer-edit-points title="Editar Slayer points"><small>POINTS</small><strong>${state.slayer.points}</strong><em>✎ editar</em></button><span><small>PRÓXIMO BÔNUS</small><strong>#${next}</strong><em>${master.name}</em></span></div>${ui.slayerEditingStreak?`<form class="slayer-streak-editor" data-slayer-streak-form><label>Streak atual<input name="streak" type="number" min="0" required value="${state.slayer.streak}" autofocus></label><p>Use o número exibido no jogo. A próxima task registrada será a <strong>#${state.slayer.streak+1}</strong>.</p><button class="primary-btn">Começar daqui</button><button type="button" class="ghost-btn" data-slayer-edit-streak>Cancelar</button></form>`:''}${ui.slayerEditingPoints?`<form class="slayer-streak-editor" data-slayer-points-form><label>Slayer points atuais<input name="points" type="number" min="0" required value="${state.slayer.points}" autofocus></label><p>Informe o saldo mostrado no jogo. Os próximos bônus serão somados a partir deste valor.</p><button class="primary-btn">Salvar pontos</button><button type="button" class="ghost-btn" data-slayer-edit-points>Cancelar</button></form>`:''}</section>`}

function taskSetupForm(){const current=state.slayer.currentTask,selected=slayerEntry(current?.monsterId||current?.name),masterKey=current?slayerMasterKey(current):state.slayer.preferredMaster;return `<form class="slayer-task-form" data-slayer-task-form><div class="form-two"><label>Task ou monstro<input name="name" list="slayerTaskNames" required value="${esc(current?.name||'')}" placeholder="Ex: Dust devils"><datalist id="slayerTaskNames">${slayerCatalog.map(item=>`<option value="${esc(item.name)}"></option>`).join('')}</datalist></label><label>Slayer Master<select name="masterKey">${slayerMasterOptions(masterKey)}</select></label></div><div class="form-two"><label>Quantidade recebida<input name="amount" type="number" min="1" value="${current?.amount||100}"></label><label>Restantes agora<input name="remaining" type="number" min="0" value="${current?.remaining??current?.amount??100}"></label></div><label>Plano para esta task<textarea name="notes" placeholder="Ex: cannon no Lighthouse, levar 2 prayer pots...">${esc(current?.notes||selected?.route||'')}</textarea></label><button class="primary-btn">${current?'Atualizar task':'Começar task'}</button></form>`}

function taskCurrentPanel(){const task=state.slayer.currentTask;if(!task)return `<div class="slayer-empty-layout"><section class="slayer-empty card"><span>☠</span><h2>Nenhuma task ativa</h2><p>Informe o monstro e a quantidade. Nada precisa vir de plugin ou API.</p>${taskSetupForm()}</section><aside class="card slayer-first-guide"><span class="eyebrow">FLUXO SIMPLES</span><ol><li>Receba a task no jogo.</li><li>Registre o nome e a quantidade aqui.</li><li>Use a rota, gear e proteção recomendados.</li><li>Marque kills ou finalize de uma vez.</li></ol></aside></div>`;
  const item=slayerEntry(task.monsterId||task.name),record=slayerRecord(item?.id||task.name),progress=currentSlayerProgress(),reward=slayerRewardPreview(slayerMasterKey(task));return `<div class="slayer-task-layout"><section class="slayer-current-card card"><div class="slayer-current-head">${item?slayerPortrait(item,'large'):'<span class="slayer-portrait large">☠</span>'}<div><span class="eyebrow">TASK EM ANDAMENTO</span><h2>${esc(task.name)}</h2><p>${esc(task.master)} · iniciada ${formatDate(task.startedAt)}</p></div><strong>${Math.max(0,task.remaining)}</strong></div>${progressBar(progress)}<div class="slayer-progress-copy"><span>${task.amount-task.remaining} derrotados</span><b>${Math.round(progress)}%</b><span>${task.amount} no total</span></div><div class="slayer-reward-preview"><span><small>AO CONCLUIR</small><strong>Task #${state.slayer.streak+1} · +${reward.points} pts</strong></span><p>${esc(reward.reason)}</p></div><div class="slayer-kill-actions"><button data-slayer-kill="1">+1 kill</button><button data-slayer-kill="5">+5</button><button data-slayer-kill="10">+10</button><button class="primary-btn" data-slayer-finish>✓ Concluir task</button></div><div class="seg-actions"><button class="ghost-btn" data-slayer-session>◷ Levar para a sessão</button><button class="ghost-btn" data-slayer-task-goal>✓ Criar meta</button><button class="ghost-btn" data-slayer-edit-task>✎ Editar</button><button class="ghost-btn danger" data-slayer-clear-task>Cancelar</button></div></section><aside class="slayer-advice card">${item?slayerAdvice(item):`<span class="eyebrow">MONSTRO PERSONALIZADO</span><h3>${esc(task.name)}</h3><p>Não encontrei esta categoria no guia local. Você ainda pode acompanhar a task normalmente.</p><a class="ghost-btn" href="https://oldschool.runescape.wiki/?search=${encodeURIComponent(task.name)}" target="_blank" rel="noreferrer">Buscar na Wiki ↗</a>`}<div class="slayer-note"><small>SEU PLANO</small><p>${esc(task.notes||'Nenhuma observação adicionada.')}</p></div></aside></div><details class="card slayer-edit-inline" ${ui.slayerEditingTask?'open':''}><summary>Editar os dados da task</summary>${taskSetupForm()}</details>`}

function slayerAdvice(item){const record=slayerRecord(item.id);return `<span class="eyebrow">PREPARAÇÃO RECOMENDADA</span><h3>${esc(item.name)}</h3><div class="advice-grid"><div><small>Fraqueza / estilo</small><strong>${esc(item.weakness)}</strong></div><div><small>Ataques</small><strong>${esc(item.attacks)}</strong></div><div><small>Proteção</small><strong>${esc(item.protection)}</strong></div><div><small>Melhor rota</small><strong>${esc(record.preferredLocation||item.route)}</strong></div></div>${item.requirements?`<p class="slayer-requirement">◆ ${esc(item.requirements)}</p>`:''}<div class="tag-row">${item.tags.map(slayerTag).join('')}</div><a href="${slayerWikiUrl(item)}" target="_blank" rel="noreferrer">Abrir guia completo na Wiki ↗</a>`}

function filteredSlayerCatalog(){const query=ui.slayerSearch.trim().toLowerCase(),slayerLevel=skill('Slayer')?.current||1;return slayerCatalog.filter(item=>ui.slayerFilter==='all'||ui.slayerFilter==='turael'&&item.turael||ui.slayerFilter==='boss'&&item.bosses.length||ui.slayerFilter==='barrage'&&item.tags.includes('Barrage')||ui.slayerFilter==='cannon'&&item.tags.includes('Cannon')||ui.slayerFilter==='gp'&&item.tags.includes('GP')).filter(item=>!ui.slayerOnlyReady||item.slayerLevel<=slayerLevel).filter(item=>!query||[item.name,item.weakness,item.locations.join(' '),item.route,item.bosses.join(' '),item.tags.join(' ')].join(' ').toLowerCase().includes(query))}
function slayerBestiaryCards(){const visible=filteredSlayerCatalog(),query=ui.slayerSearch.trim().toLowerCase();return visible.map(item=>{const ready=slayerReady(item),favorite=state.slayer.favorites.includes(item.id),blocked=state.slayer.blocks.includes(item.id),matchedVariant=query&&item.bosses.find(name=>name.toLowerCase().includes(query));return `<article class="slayer-monster-card ${ui.slayerSelectedId===item.id?'selected':''} ${blocked?'is-blocked':''}"><button class="slayer-card-main" data-slayer-monster="${item.id}">${slayerPortrait(item)}<span><small>${item.turael?'TURAEL · ':''}${item.slayerLevel>1?`${item.slayerLevel} SLAYER`:'SEM REQUISITO'}</small><strong>${esc(item.name)}</strong><em>${matchedVariant?`Inclui ${esc(matchedVariant)} · `:''}${esc(item.weakness)}</em></span><b class="${ready?'ready':'locked'}">${ready?'Pronto':`Nível ${item.slayerLevel}`}</b></button><div><button data-slayer-favorite="${item.id}" title="Favoritar">${favorite?'★':'☆'}</button><button data-slayer-block="${item.id}" title="Marcar como bloqueada">${blocked?'Desbloquear':'Bloquear'}</button></div></article>`}).join('')||emptyState('⌕','Nenhum monstro encontrado','Tente buscar pelo nome, estilo, local ou boss.')}
function refreshSlayerBestiary(){const visible=filteredSlayerCatalog();if(!visible.some(item=>item.id===ui.slayerSelectedId))ui.slayerSelectedId=visible[0]?.id||null;const target=document.querySelector('.slayer-monster-list');if(target)target.innerHTML=slayerBestiaryCards();const detail=document.querySelector('.slayer-detail');if(detail)detail.outerHTML=slayerDetail(slayerCatalog.find(item=>item.id===ui.slayerSelectedId))}

function slayerStartForm(item){const suggestedMaster=item.turael?'turael':state.slayer.preferredMaster,reward=slayerRewardPreview(suggestedMaster);return `<form class="slayer-start-form" data-slayer-start-form><input type="hidden" name="monsterId" value="${item.id}"><span class="eyebrow">REGISTRAR TASK RECEBIDA</span><div class="form-two"><label>Slayer Master<select name="masterKey">${slayerMasterOptions(suggestedMaster)}</select></label><label>Quantidade<input name="amount" type="number" min="1" value="${item.turael?25:100}" required></label></div><div class="slayer-start-reward" data-slayer-start-reward><strong>Task #${state.slayer.streak+1} · +${reward.points} pts</strong><span>${esc(reward.reason)}</span></div><div class="seg-actions"><button class="primary-btn">Confirmar e começar</button><button type="button" class="ghost-btn" data-slayer-start-cancel>Cancelar</button></div></form>`}
function slayerDetail(item){if(!item)return `<aside class="slayer-detail card"><span class="slayer-detail-rune">⌕</span><h3>Escolha um monstro</h3><p>Clique em uma task para ver fraquezas, locais, variantes e atalhos.</p></aside>`;const record=slayerRecord(item.id),ready=slayerReady(item);return `<aside class="slayer-detail card"><div class="slayer-detail-hero">${slayerPortrait(item,'large')}<div><span class="eyebrow">${item.turael?'TASK DO TURAEL':'BESTIÁRIO DE SLAYER'}</span><h2>${esc(item.name)}</h2><p class="${ready?'ready-text':'locked-text'}">${ready?'✓ Seu nível de Slayer está pronto':`Precisa de ${item.slayerLevel} Slayer · você tem ${skill('Slayer')?.current||1}`}</p></div></div><div class="slayer-detail-grid"><div><small>Fraqueza / estilo</small><strong>${esc(item.weakness)}</strong></div><div><small>Ataques recebidos</small><strong>${esc(item.attacks)}</strong></div><div><small>Proteção</small><strong>${esc(item.protection)}</strong></div><div><small>Requisitos</small><strong>${esc(item.requirements||'Nenhum especial')}</strong></div></div><section><small>ONDE ENCONTRAR</small>${item.locations.map(location=>`<p class="location-line">⌖ ${esc(location)}</p>`).join('')}<p class="route-line"><b>Rota sugerida:</b> ${esc(item.route)}</p></section>${item.bosses.length?`<section><small>VARIANTES / BOSSES QUE CONTAM</small><div class="tag-row">${item.bosses.map(slayerTag).join('')}</div></section>`:''}<section><small>SEU REGISTRO</small><form class="slayer-record-form" data-slayer-record-form><input type="hidden" name="id" value="${item.id}"><div class="form-two"><label>Kills registradas<input name="kills" type="number" min="0" value="${record.kills||0}"></label><label>Local preferido<input name="preferredLocation" value="${esc(record.preferredLocation||'')}" placeholder="Ex: Catacombs"></label></div><label>Anotações<textarea name="notes" placeholder="Gear, drops, rota pessoal...">${esc(record.notes||'')}</textarea></label><button class="primary-btn">Salvar meu método</button></form></section>${ui.slayerStartId===item.id?slayerStartForm(item):`<div class="slayer-detail-actions"><button data-slayer-start="${item.id}">☠ Começar esta task</button><button data-slayer-monster-goal="${item.id}">✓ Criar meta de kills</button><button data-slayer-gear="${item.id}">♟ Abrir Gear Lab</button><a href="${slayerWikiUrl(item)}" target="_blank" rel="noreferrer">Wiki ↗</a></div>`}</aside>`}

function bestiaryPanel(){const filters=[['all','Todos'],['turael','Turael'],['boss','Com boss'],['barrage','Barrage'],['cannon','Cannon'],['gp','GP']];return `<div class="slayer-bestiary-layout"><section><div class="filterbar slayer-filterbar"><label class="search"><span>⌕</span><input data-slayer-search value="${esc(ui.slayerSearch)}" placeholder="Buscar monstro, fraqueza, local ou boss..."></label><select data-slayer-filter>${filters.map(([value,label])=>`<option value="${value}" ${ui.slayerFilter===value?'selected':''}>${label}</option>`).join('')}</select><label class="toggle-line"><input data-slayer-ready type="checkbox" ${ui.slayerOnlyReady?'checked':''}> Só acessíveis</label></div><div class="slayer-monster-list">${slayerBestiaryCards()}</div><div class="wiki-fallback"><span>Não achou um NPC específico?</span><a href="https://oldschool.runescape.wiki/?search=${encodeURIComponent(ui.slayerSearch||'Slayer monsters')}" target="_blank" rel="noreferrer">Buscar “${esc(ui.slayerSearch||'Slayer monsters')}” na Wiki ↗</a></div></section>${slayerDetail(slayerCatalog.find(item=>item.id===ui.slayerSelectedId))}</div>`}

function boostStatus(){const next=nextSlayerMilestone(),tasksLeft=Math.max(0,next-state.slayer.streak),master=slayerMasters[state.slayer.preferredMaster]||slayerMasters.konar,potential=milestonePoints(state.slayer.preferredMaster,next);return `<section class="boost-command card"><div><span class="eyebrow">ROTA ATÉ O BÔNUS</span><h2>${tasksLeft<=1?'A próxima é a task de bônus!':`${tasksLeft-1} tasks rápidas + 1 de bônus`}</h2><p>${tasksLeft<=1?`Pegue a task #${next} com ${master.name}.`:`Faça as próximas ${tasksLeft-1} com Turael/Aya e a #${next} com ${master.name}.`}</p></div><div class="boost-ring" style="--boost:${Math.round(((state.slayer.streak%10)/10)*100)}"><strong>#${state.slayer.streak+1}</strong><small>próxima task</small></div><div class="boost-reward"><small>BÔNUS ESTIMADO</small><strong>${potential} pts</strong><span>${master.name} · ${milestoneMultiplier(next)}×</span></div></section>`}

function turaelQuickRoutes(){return slayerCatalog.filter(item=>item.turael).map(item=>`<article class="turael-route ${state.slayer.blocks.includes(item.id)?'is-blocked':''}">${slayerPortrait(item)}<div><strong>${esc(item.name)}</strong><small>${esc(item.route)}</small><span>${item.tags.includes('Cannon')?'Cannon recomendado':'Variante de baixo nível'}</span></div><button data-slayer-start="${item.id}">Iniciar</button></article>`).join('')}
function boostPanel(){const master=slayerMasters[state.slayer.preferredMaster]||slayerMasters.konar,isBonus=(state.slayer.streak+1)%10===0;return `${boostStatus()}<div class="boost-layout"><section class="card boost-guide"><span class="eyebrow">GUIA INTERATIVO</span><h2>Turael Boosting sem confusão</h2><div class="boost-warning"><b>Boosting mantém a streak.</b><span>Turael/Aya dá tasks rápidas; o master forte entrega os pontos nas milestones.</span></div><ol class="boost-steps"><li><span>1</span><div><strong>Prepare o kit</strong><p>Expeditious bracelets, teleports, cannon se possível e NPC Contact para reduzir deslocamentos.</p></div></li><li><span>2</span><div><strong>Faça tasks rápidas</strong><p>Use Turael/Aya até chegar à task anterior ao bônus.</p></div></li><li><span>3</span><div><strong>Troque no momento certo</strong><p>Pegue a #10, #50, #100, #250 ou #1000 com ${master.name}.</p></div></li><li><span>4</span><div><strong>Registre e repita</strong><p>O painel atualiza streak, pontos e o próximo marco.</p></div></li></ol><div class="danger-note"><strong>⚠ Boosting não é Turael skipping</strong><p>Pedir ao Turael para substituir uma task difícil de outro master zera sua streak normal. Use isso apenas quando quiser pular tasks, não para farmar pontos.</p></div><a href="https://oldschool.runescape.wiki/w/Slayer_reward_point#Turael_boosting" target="_blank" rel="noreferrer">Guia oficial completo na OSRS Wiki ↗</a></section><aside class="card boost-controls"><span class="eyebrow">SEU RASTREADOR</span><h3>Configurar campanha</h3><form data-slayer-boost-form class="form"><div class="form-two"><label>Streak atual<input name="streak" type="number" min="0" value="${state.slayer.streak}"></label><label>Slayer points<input name="points" type="number" min="0" value="${state.slayer.points}"></label></div><label>Master das milestones<select name="preferredMaster">${Object.entries(slayerMasters).filter(([key])=>key!=='turael').map(([key,item])=>`<option value="${key}" ${state.slayer.preferredMaster===key?'selected':''}>${item.name} · ${item.points} pts</option>`).join('')}</select></label><label>Meta de pontos<input name="boostTarget" type="number" min="1" value="${state.slayer.boostTarget}"></label><div class="boost-toggles">${[['cannon','Cannon'],['barrage','Burst/Barrage'],['npcContact','NPC Contact'],['expeditious','Expeditious bracelets'],['ironman','Modo Ironman']].map(([key,label])=>`<label><input type="checkbox" name="${key}" ${state.slayer.setup[key]?'checked':''}> ${label}</label>`).join('')}</div><button class="primary-btn">Salvar rastreador</button></form><div class="boost-manual-actions"><button data-boost-complete="turael" ${isBonus?'disabled':''}>+ Task Turael</button><button data-boost-complete="milestone" ${isBonus?'':'disabled'}>+ Task de bônus</button><button data-boost-undo ${slayerCanUndo()?'':'disabled'}>↶ Desfazer última</button></div><div class="points-progress"><span><b>${state.slayer.points}</b> / ${state.slayer.boostTarget} pontos</span>${progressBar(safePercent(state.slayer.points,state.slayer.boostTarget))}</div></aside></div><section class="card turael-list"><div class="section-heading"><div><span class="eyebrow">ROTAS RÁPIDAS</span><h2>Tasks do Turael / Aya</h2></div><span class="pill">${slayerCatalog.filter(item=>item.turael).length} categorias</span></div><div class="turael-route-grid">${turaelQuickRoutes()}</div></section>`}

function slayerPlannerPanel(){const history=state.slayer.taskHistory.slice(0,12),blocked=state.slayer.blocks.map(slayerEntry).filter(Boolean),favorites=state.slayer.favorites.map(slayerEntry).filter(Boolean),recorded=Object.entries(state.slayer.records).map(([key,value])=>({item:slayerEntry(key),...value})).filter(entry=>entry.item&&(entry.kills||entry.notes||entry.preferredLocation)).sort((a,b)=>b.kills-a.kills);return `<div class="slayer-summary-grid"><article><small>Tasks registradas</small><strong>${state.slayer.taskHistory.length}</strong><span>${state.slayer.taskHistory.filter(item=>item.kind==='milestone').length} milestones</span></article><article><small>Monstros favoritos</small><strong>${favorites.length}</strong><span>atalhos do seu perfil</span></article><article><small>Lista de bloqueio</small><strong>${blocked.length}</strong><span>planejamento pessoal</span></article><article><small>Kills manuais</small><strong>${recorded.reduce((sum,item)=>sum+Number(item.kills||0),0)}</strong><span>no bestiário</span></article></div><div class="slayer-planner-grid"><section class="card"><div class="section-heading"><div><span class="eyebrow">PREFERÊNCIAS</span><h2>Minha lista de Slayer</h2></div></div><h3>★ Favoritas</h3><div class="planner-chip-list">${favorites.map(item=>`<button data-slayer-monster="${item.id}">${esc(item.name)} <span>→</span></button>`).join('')||'<p class="muted">Favorite monstros no Bestiário.</p>'}</div><h3>⊘ Bloqueadas / evitar</h3><div class="planner-chip-list blocked">${blocked.map(item=>`<button data-slayer-block="${item.id}">${esc(item.name)} <span>×</span></button>`).join('')||'<p class="muted">Marque tasks que você prefere evitar.</p>'}</div><p class="calc-disclaimer">Esta lista é um planejador pessoal. Confirme seus blocks no menu do Slayer Master dentro do jogo.</p></section><section class="card"><div class="section-heading"><div><span class="eyebrow">DIÁRIO DE CAÇADAS</span><h2>Últimas tasks</h2></div></div><div class="slayer-history">${history.map(entry=>`<article><span>${entry.kind==='milestone'?'★':'☠'}</span><div><strong>${esc(entry.name||entry.master||'Task concluída')}</strong><small>${entry.streak} streak · ${entry.pointsGained?`+${entry.pointsGained} pts · `:''}${formatDate(entry.date)}</small></div></article>`).join('')||emptyState('▤','Nenhuma task registrada','Conclua uma task no rastreador para começar o diário.')}</div></section></div><section class="card recorded-monsters"><div class="section-heading"><div><span class="eyebrow">MÉTODOS PESSOAIS</span><h2>Seus registros do Bestiário</h2></div><button class="ghost-btn" data-slayer-tab="bestiary">Abrir Bestiário</button></div><div class="record-grid">${recorded.map(entry=>`<button data-slayer-monster="${entry.item.id}">${slayerPortrait(entry.item)}<span><strong>${esc(entry.item.name)}</strong><small>${entry.kills||0} kills · ${esc(entry.preferredLocation||'sem local favorito')}</small></span></button>`).join('')||'<p class="muted">Salve kills, locais e anotações nos monstros para vê-los aqui.</p>'}</div></section>`}

function slayerPage(){if(!Object.keys(slayerImages).length&&!ui.slayerImageLoading&&!slayerImagesAttempted)setTimeout(()=>loadSlayerImages(false),0);const body=ui.slayerTab==='bestiary'?bestiaryPanel():ui.slayerTab==='boost'?boostPanel():ui.slayerTab==='planner'?slayerPlannerPanel():taskCurrentPanel();return `${sectionHead('CENTRAL DE SLAYER','Caçadas, rotas e recompensas',`<div class="seg-actions"><button class="ghost-btn" data-load-slayer-images ${ui.slayerImageLoading?'disabled':''}>${ui.slayerImageLoading?'Buscando imagens…':'▣ Atualizar imagens'}</button><a class="ghost-btn" href="https://oldschool.runescape.wiki/w/Slayer" target="_blank" rel="noreferrer">OSRS Wiki ↗</a></div>`)}${slayerHero()}${slayerTabs()}<div class="slayer-content">${body}</div>`}

const slayerOriginalPageContent=pageContent;
pageContent=function(){if(route==='slayer')return slayerPage();return slayerOriginalPageContent()};

const slayerOriginalGoalProgress=goalProgress;
goalProgress=function(goal){if(goal.mode==='slayerTask'){const task=state.slayer.currentTask;if(task&&slug(task.name)===slug(goal.slayerMonster||goal.title))return currentSlayerProgress();return goal.status==='done'?100:clamp(goal.progress)}if(goal.mode==='slayerKills'){return safePercent(slayerRecord(goal.slayerMonster).kills,goal.target)}return slayerOriginalGoalProgress(goal)};
const slayerOriginalTypeLabel=typeLabel;
typeLabel=function(type){return type==='slayer'?'Slayer':slayerOriginalTypeLabel(type)};

const slayerOriginalGoalDrawer=goalDrawer;
goalDrawer=function(goalId,eraId='',questName=''){const goal=goalById(goalId),html=slayerOriginalGoalDrawer(goalId,eraId,questName);const mode=goal?.mode||'manual',modeOptions=`<option value="slayerTask" ${mode==='slayerTask'?'selected':''}>Task atual de Slayer</option><option value="slayerKills" ${mode==='slayerKills'?'selected':''}>Kills registradas no Bestiário</option>`;const typeOption=`<option value="slayer" ${goal?.type==='slayer'?'selected':''}>Slayer</option>`;const linkage=`<label>Monstro / task de Slayer<select name="slayerMonster"><option value="">Selecione</option>${slayerCatalog.map(item=>`<option value="${item.id}" ${slug(goal?.slayerMonster)===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select><small>Task atual acompanha restantes; kills usa o contador salvo no Bestiário.</small></label>`;return html.replace('</select></label><label>Status',typeOption+'</select></label><label>Status').replace('</select></label><div class="linkage-fields">',modeOptions+'</select></label><div class="linkage-fields">'+linkage)};

function createSlayerGoal(item,mode='slayerKills',target=100){const existing=state.goals.find(goal=>goal.mode===mode&&slug(goal.slayerMonster)===item.id&&goal.status!=='archived');if(existing){ui.drawer={type:'goal',id:existing.id};render();return}const goal={id:id('goal'),title:mode==='slayerTask'?`Concluir task de ${item.name}`:`${item.name}: ${target} kills`,description:`Objetivo criado pela Central de Slayer. ${item.route}`,type:'slayer',status:'active',mode,slayerMonster:item.id,target,progress:0,eraId:state.eras.find(era=>/slayer|pvm/i.test(era.title))?.id||state.eras[0]?.id||null,priority:state.goals.length+1};state.goals.push(goal);save('Meta de Slayer criada e vinculada ao Roadmap');ui.drawer={type:'goal',id:goal.id};render()}

function setCurrentSlayerTask(item,name,amount=100,masterKey='turael',notes=''){const master=slayerMasters[masterKey]||slayerMasters.turael;state.slayer.currentTask={monsterId:item?.id||slug(name),name:item?.name||name,amount:Math.max(1,Number(amount)||100),remaining:Math.max(0,Number(amount)||100),masterKey,master:master.name,notes:notes||item?.route||'',startedAt:new Date().toISOString()};save('Task de Slayer iniciada');ui.slayerStartId=null;ui.slayerTab='task';render()}
function finishCurrentSlayerTask(){const task=state.slayer.currentTask;if(!task)return;const record=slayerRecord(task.monsterId||task.name);record.kills=Number(record.kills||0)+Math.max(0,Number(task.amount)||0);record.lastDone=new Date().toISOString();state.slayer.streak+=1;const masterKey=slayerMasterKey(task),pointsGained=milestonePoints(masterKey,state.slayer.streak);state.slayer.points+=pointsGained;state.slayer.taskHistory.unshift({id:id('slayer'),name:task.name,master:task.master,masterKey,amount:task.amount,streak:state.slayer.streak,pointsGained,kind:milestoneMultiplier(state.slayer.streak)>1?'milestone':'task',date:new Date().toISOString()});state.slayer.taskHistory=state.slayer.taskHistory.slice(0,100);addHistory('pvm',`${task.name} concluída`,`Task #${state.slayer.streak}${pointsGained?` · +${pointsGained} Slayer points`:''}.`);state.slayer.currentTask=null;save('Task concluída');render()}

document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;
  if(button.dataset.slayerTab){ui.slayerTab=button.dataset.slayerTab;if(ui.slayerTab==='bestiary'&&!ui.slayerSelectedId)ui.slayerSelectedId=filteredSlayerCatalog()[0]?.id||null;render();return}
  if(button.hasAttribute('data-slayer-edit-streak')){ui.slayerEditingStreak=!ui.slayerEditingStreak;ui.slayerEditingPoints=false;render();return}
  if(button.hasAttribute('data-slayer-edit-points')){ui.slayerEditingPoints=!ui.slayerEditingPoints;ui.slayerEditingStreak=false;render();return}
  if(button.hasAttribute('data-load-slayer-images')){loadSlayerImages(true);return}
  if(button.dataset.slayerMonster){ui.slayerSelectedId=button.dataset.slayerMonster;ui.slayerTab='bestiary';render();return}
  if(button.dataset.slayerFavorite){const key=button.dataset.slayerFavorite;state.slayer.favorites=state.slayer.favorites.includes(key)?state.slayer.favorites.filter(item=>item!==key):[...state.slayer.favorites,key];save(state.slayer.favorites.includes(key)?'Adicionado aos favoritos':'Removido dos favoritos',true);render();return}
  if(button.dataset.slayerBlock){const key=button.dataset.slayerBlock;state.slayer.blocks=state.slayer.blocks.includes(key)?state.slayer.blocks.filter(item=>item!==key):[...state.slayer.blocks,key];save(state.slayer.blocks.includes(key)?'Marcado para bloquear/evitar':'Removido da lista de bloqueio',true);render();return}
  if(button.dataset.slayerStart){const item=slayerEntry(button.dataset.slayerStart);if(item){ui.slayerStartId=item.id;ui.slayerSelectedId=item.id;ui.slayerTab='bestiary';render()}return}
  if(button.hasAttribute('data-slayer-start-cancel')){ui.slayerStartId=null;render();return}
  if(button.dataset.slayerKill){const task=state.slayer.currentTask;if(task){task.remaining=Math.max(0,task.remaining-Number(button.dataset.slayerKill));if(task.remaining===0)toast('Quantidade zerada — conclua a task para registrar a streak.');save('Kill registrada',true);render()}return}
  if(button.hasAttribute('data-slayer-finish')){finishCurrentSlayerTask();return}
  if(button.hasAttribute('data-slayer-edit-task')){ui.slayerEditingTask=!ui.slayerEditingTask;render();return}
  if(button.hasAttribute('data-slayer-clear-task')){if(confirm('Cancelar esta task no painel? Isso não altera sua streak registrada.')){state.slayer.currentTask=null;save('Task removida do painel');render()}return}
  if(button.hasAttribute('data-slayer-session')){const task=state.slayer.currentTask;if(task&&!state.tasks.some(entry=>!entry.done&&entry.slayerTask)){state.tasks.unshift({id:id('task'),text:`Slayer: ${task.name} (${task.remaining} restantes)`,done:false,goalId:null,slayerTask:true});save('Task adicionada à sessão de hoje')}else toast('Esta task já está na sessão.');return}
  if(button.hasAttribute('data-slayer-task-goal')){const task=state.slayer.currentTask,item=slayerEntry(task?.monsterId||task?.name);if(task&&item)createSlayerGoal(item,'slayerTask',task.amount);return}
  if(button.dataset.slayerMonsterGoal){const item=slayerEntry(button.dataset.slayerMonsterGoal);if(!item)return;const record=slayerRecord(item.id),suggested=Math.max(25,Math.ceil((Number(record.kills||0)+25)/25)*25),target=Number(prompt(`Meta de kills para ${item.name}:`,suggested));if(target>0)createSlayerGoal(item,'slayerKills',target);return}
  if(button.dataset.slayerGear){ui.pvmTab='gear';const item=slayerEntry(button.dataset.slayerGear),boss=item?.bosses?.[0],matched=state.bosses.catalog.find(entry=>slug(entry.name)===slug(boss));if(matched)state.gearLab.selectedBossId=matched.id;navigate('pvm');return}
  if(button.dataset.boostComplete){const next=state.slayer.streak+1,isMilestone=button.dataset.boostComplete==='milestone',masterKey=isMilestone?state.slayer.preferredMaster:'turael',master=slayerMasters[masterKey],pointsGained=isMilestone?milestonePoints(masterKey,next):0;state.slayer.streak=next;state.slayer.points+=pointsGained;state.slayer.taskHistory.unshift({id:id('slayer'),name:isMilestone?`Task de bônus com ${master.name}`:'Task rápida de Turael/Aya',master:master.name,amount:0,streak:next,pointsGained,kind:isMilestone?'milestone':'task',date:new Date().toISOString()});addHistory('pvm',`Slayer streak #${next}`,isMilestone?`${master.name} · +${pointsGained} pontos.`:'Task rápida concluída.');save(isMilestone?`+${pointsGained} Slayer points`:'Streak avançada');render();return}
  if(button.hasAttribute('data-boost-undo')){if(!slayerCanUndo()){toast('Você chegou ao ponto inicial configurado.');return}const last=state.slayer.taskHistory.shift();if(last){state.slayer.streak=Math.max(Number(state.slayer.streakBaseline)||0,state.slayer.streak-1);state.slayer.points=Math.max(0,state.slayer.points-Number(last.pointsGained||0));save('Último registro desfeito');render()}return}
  if(button.hasAttribute('data-restore-slayer')){if(confirm('Restaurar todos os personagens para o estado anterior à Central de Slayer?')){try{const incoming=JSON.parse(localStorage.getItem(SLAYER_BACKUP_KEY));if(incoming?.profiles){profileHub=incoming;profileHub.profiles.forEach(profile=>profile.state=mergeDefaults(profile.state));profileHub.activeId=profileHub.profiles.some(profile=>profile.id===incoming.activeId)?incoming.activeId:profileHub.profiles[0].id;state=mergeDefaults(activeProfile().state);persistProfiles();navigate('dashboard');toast('Cópia anterior restaurada')}else throw new Error()}catch{toast('A cópia de segurança não pôde ser restaurada.')}}return}
});

document.addEventListener('input',event=>{if(event.target.matches('[data-slayer-search]')){ui.slayerSearch=event.target.value;clearTimeout(ui.slayerSearchTimer);ui.slayerSearchTimer=setTimeout(refreshSlayerBestiary,100)}});
document.addEventListener('change',event=>{const input=event.target;if(input.matches('[data-slayer-filter]')){ui.slayerFilter=input.value;render()}if(input.matches('[data-slayer-ready]')){ui.slayerOnlyReady=input.checked;render()}if(input.matches('[data-slayer-start-form] select[name="masterKey"]')){const reward=slayerRewardPreview(input.value),target=input.closest('form')?.querySelector('[data-slayer-start-reward]');if(target)target.innerHTML=`<strong>Task #${state.slayer.streak+1} · +${reward.points} pts</strong><span>${esc(reward.reason)}</span>`}});

document.addEventListener('submit',event=>{const form=event.target,data=new FormData(form);
  if(form.matches('[data-slayer-start-form]')){event.preventDefault();const item=slayerEntry(data.get('monsterId')),masterKey=data.get('masterKey'),amount=Math.max(1,Number(data.get('amount'))||100);if(item)setCurrentSlayerTask(item,item.name,amount,masterKey,item.route);return}
  if(form.matches('[data-slayer-task-form]')){event.preventDefault();const item=slayerEntry(data.get('name')),amount=Math.max(1,Number(data.get('amount'))||100),remaining=Math.max(0,Math.min(amount,Number(data.get('remaining')))),masterKey=data.get('masterKey'),master=slayerMasters[masterKey]||slayerMasters.turael;state.slayer.currentTask={monsterId:item?.id||slug(data.get('name')),name:item?.name||data.get('name').trim(),amount,remaining,masterKey,master:master.name,notes:data.get('notes').trim(),startedAt:state.slayer.currentTask?.startedAt||new Date().toISOString()};save('Task atualizada');ui.slayerEditingTask=false;render();return}
  if(form.matches('[data-slayer-record-form]')){event.preventDefault();const record=slayerRecord(data.get('id'));record.kills=Math.max(0,Number(data.get('kills'))||0);record.preferredLocation=data.get('preferredLocation').trim();record.notes=data.get('notes').trim();save('Método pessoal salvo');render();return}
  if(form.matches('[data-slayer-streak-form]')){event.preventDefault();const previous=state.slayer.streak,next=Math.max(0,Math.floor(Number(data.get('streak'))||0));state.slayer.streak=next;state.slayer.streakBaseline=next;state.slayer.trackingStartedAt=new Date().toISOString();ui.slayerEditingStreak=false;if(previous!==next)addHistory('pvm','Streak de Slayer ajustada',`${previous} → ${next}. O rastreador continuará pela task #${next+1}.`);save(`Streak configurada em ${next}`);render();return}
  if(form.matches('[data-slayer-points-form]')){event.preventDefault();const previous=state.slayer.points,next=Math.max(0,Math.floor(Number(data.get('points'))||0));state.slayer.points=next;ui.slayerEditingPoints=false;if(previous!==next)addHistory('pvm','Slayer points ajustados',`${previous} → ${next} pontos.`);save(`Slayer points configurados em ${next}`);render();return}
  if(form.matches('[data-slayer-boost-form]')){event.preventDefault();const previous=state.slayer.streak,next=Math.max(0,Math.floor(Number(data.get('streak'))||0));state.slayer.streak=next;if(previous!==next){state.slayer.streakBaseline=next;state.slayer.trackingStartedAt=new Date().toISOString();addHistory('pvm','Streak de Slayer ajustada',`${previous} → ${next}. O rastreador continuará pela task #${next+1}.`)}state.slayer.points=Math.max(0,Number(data.get('points'))||0);state.slayer.preferredMaster=data.get('preferredMaster');state.slayer.boostTarget=Math.max(1,Number(data.get('boostTarget'))||250);['cannon','barrage','npcContact','expeditious','ironman'].forEach(key=>state.slayer.setup[key]=data.get(key)==='on');save('Campanha de boosting atualizada');render();return}
});

document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-goal-form]'))return;const data=new FormData(form),mode=data.get('mode');if(!['slayerTask','slayerKills'].includes(mode))return;event.preventDefault();event.stopImmediatePropagation();const monsterId=data.get('slayerMonster');if(!monsterId){toast('Selecione o monstro ou a task de Slayer.');return}const goalId=data.get('id');let goal=goalId?goalById(goalId):null,before=goal?.status;if(!goal){goal={id:id('goal'),priority:state.goals.length+1};state.goals.push(goal)}Object.assign(goal,{title:data.get('title').trim(),description:data.get('description').trim(),type:'slayer',status:data.get('status'),mode,eraId:data.get('eraId')||null,slayerMonster:monsterId,target:Number(data.get('target'))||100,progress:Number(data.get('progress'))||0});if(goalProgress(goal)>=100)goal.status='done';if(goal.status==='done'&&before!=='done')addHistory('goal',`${goal.title} concluída`,'Meta de Slayer finalizada.');delete ui.drawerDrafts[drawerKey()];ui.skipDrawerDraft=true;save(goalId?'Meta de Slayer atualizada':'Meta de Slayer criada');ui.drawer=null;render()},{capture:true});

const slayerOriginalSettingsPage=settingsPage;
settingsPage=function(){return `${slayerOriginalSettingsPage()}<section class="settings-card expansion-safety slayer-safety">${sectionHead('BACKUP DA CENTRAL DE SLAYER','Segurança dos personagens')}<p>Uma cópia automática de todos os personagens foi salva antes desta atualização.</p><button class="ghost-btn danger" data-restore-slayer>Restaurar estado pré-Slayer</button></section>`};

const slayerRequestedRoute=location.hash.slice(1);if(slayerRequestedRoute==='slayer'){route='slayer';render()}
setTimeout(()=>loadSlayerImages(false),0);
